import{c as t,Q as a,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"How to Actually Use Claude Code Dynamic Workflows","description":"","frontmatter":{"url":"https://x.com/nateherk/status/2060779931114652016","title":"How to Actually Use Claude Code Dynamic Workflows","author":"Nate Herk","archived":"2026-06-15T00:00:00.000Z","handle":"@nateherk","published":"2026-05-30T00:00:00.000Z","score":"9.3/10","stats":"261 likes · 25 retweets","tags":["dynamic-workflows","ultracode","goal-vs-workflow","cost-management","skills-vs-subagents","ladder-framework"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-05-30-@nateherk-652016.md","filePath":"research/tweets/2026-05-30-@nateherk-652016.md","lastUpdated":1785909234000}'),l={name:"research/tweets/2026-05-30-@nateherk-652016.md"};function n(s,e,i,d,h,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="how-to-actually-use-claude-code-dynamic-workflows-—-nateherk" tabindex="-1">How to Actually Use Claude Code Dynamic Workflows — @nateherk <a class="header-anchor" href="#how-to-actually-use-claude-code-dynamic-workflows-—-nateherk" aria-label="Permalink to &quot;How to Actually Use Claude Code Dynamic Workflows — @nateherk&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/nateherk/status/2060779931114652016" target="_blank" rel="noreferrer">https://x.com/nateherk/status/2060779931114652016</a><strong>作者</strong>：Nate Herk（@nateherk） <strong>發布日期</strong>：2026-05-30 <strong>收錄日期</strong>：2026-06-15 <strong>類型</strong>：Twitter Article（長文） <strong>統計</strong>：261 likes · 25 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><h2 id="one-prompt-burned-half-my-claude-plan" tabindex="-1">One Prompt Burned Half My Claude Plan <a class="header-anchor" href="#one-prompt-burned-half-my-claude-plan" aria-label="Permalink to &quot;One Prompt Burned Half My Claude Plan&quot;">​</a></h2><p>Claude Opus 4.8 shipped a new feature called dynamic workflows.</p><p>I ran one prompt and it ate half of my $200 a month plan in about 30 minutes.</p><p>So I spent the week figuring out what these actually are, how they stack up against everything Claude Code already has, and when they&#39;re worth the spend.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>→ A dynamic workflow is Claude Code writing a script that spins up a ton of agents in parallel, then merges every result into one answer</p><p>→ One prompt cost me half my monthly plan in 30 minutes, so scope is everything</p><p>→ The ladder: ask Claude → Skill → Subagent → Agent Team → /goal → workflow</p><p>→ /goal is depth (loop until done = true), a workflow is width (50 agents side by side)</p><p>→ ultracode mode and /deep-research are the hidden pieces worth knowing</p><p>→ Most knowledge work doesn&#39;t need a workflow, and that&#39;s completely fine</p><h2 id="what-a-dynamic-workflow-actually-is" tabindex="-1">What A Dynamic Workflow Actually Is <a class="header-anchor" href="#what-a-dynamic-workflow-actually-is" aria-label="Permalink to &quot;What A Dynamic Workflow Actually Is&quot;">​</a></h2><p>I ran one that audited all 41 of my Claude Code skills.</p><p>It spun up 41 Haiku agents at once, one per skill, scored them in parallel, then fed everything into a single Opus synthesis agent.</p><p>Because the agents ran side by side, it was fast. It just ate a ton of input tokens. Roughly 5 million.</p><p>Not much came back out, so it wasn&#39;t crazy expensive. And I ended up with an HTML file that ranked every skill worst to best, gave me feedback on how to fix each one, and flagged patterns to watch as I build more.</p><p>Here&#39;s the part that makes it different from everything else in Claude Code.</p><p>Normally the plan lives with Claude in your main session. With a workflow, Claude writes a JavaScript file, and that file is what gets executed.</p><p>You describe the end goal. Claude turns it into a script that spins up and delegates all the agents on its own.</p><p>And those scripts can be saved and rerun whenever you want.</p><h2 id="the-ladder-from-asking-claude-to-workflows" tabindex="-1">The Ladder: From Asking Claude To Workflows <a class="header-anchor" href="#the-ladder-from-asking-claude-to-workflows" aria-label="Permalink to &quot;The Ladder: From Asking Claude To Workflows&quot;">​</a></h2><p>Skills, subagents, agent teams, and workflows all feel similar. They&#39;re built for very different jobs.</p><p>→ A <strong>Skill</strong> is a reusable recipe. You can run it yourself, trigger it as an automation, or let a subagent or a workflow run it.</p><p>→ A <strong>Subagent</strong> is a parallel worker with its own context window, so it keeps your main session clean. Subagents can&#39;t talk to each other. They only report back to you.</p><p>→ An <strong>Agent Team</strong> is a small crew that does talk to each other. Shared task list, individual roles, individual tools. Think war rooms and councils where agents debate toward one goal. More power, more cost.</p><p>→ A <strong>Workflow</strong> is Claude writing a script that runs many agents, sometimes hundreds. They work alone like subagents, then all the results merge and come back to the main session.</p><p>The real variable across all four is how many agents are in the loop and whether they can talk to each other.</p><p>The ladder (bottom to top):</p><ol><li>Just talk to Claude Code</li><li>A process you repeat → Skill</li><li>Work that should run parallel → Subagent</li><li>Subagents that need to talk → Agent Team</li><li>A giant parallel job → dynamic workflow</li></ol><h2 id="depth-vs-width-goal-vs-workflow" tabindex="-1">Depth vs Width: /goal vs Workflow <a class="header-anchor" href="#depth-vs-width-goal-vs-workflow" aria-label="Permalink to &quot;Depth vs Width: /goal vs Workflow&quot;">​</a></h2><p>/goal is <strong>depth</strong>. It&#39;s a loop. One agent takes multiple passes, checking whether done = true, until the criteria is met. You could let it run 24 hours.</p><p>A workflow is <strong>width</strong>. A bunch of subagents doing different things at the same time, synthesized at the end. 50+ agents running horizontally.</p><p>The wild combo would be a workflow nested inside a /goal. Very powerful, and a very fast way to burn money.</p><h2 id="the-money-part" tabindex="-1">The Money Part <a class="header-anchor" href="#the-money-part" aria-label="Permalink to &quot;The Money Part&quot;">​</a></h2><p>The bill depends on how big a job you point it at. Each agent is a full Claude call with its own window.</p><p>Most of the cost lands on input tokens. Input is cheaper than output, but volume still stings.</p><p>My ugly example: I asked it to search my entire desktop. It crawled every local file and every repo. That&#39;s the run that ate half my plan.</p><p>Before you fire one off: → Bound the scope. → Name the deliverable. → Put all the worker agents on Haiku.</p><h2 id="running-one-yourself" tabindex="-1">Running One Yourself <a class="header-anchor" href="#running-one-yourself" aria-label="Permalink to &quot;Running One Yourself&quot;">​</a></h2><p>The prompt I used:</p><blockquote><p>&quot;Run a workflow that audits all of my Claude Code skills in two places, my user level global skills and this project&#39;s skills. Grade on clarity, frontmatter pass/fail, and trigger quality, and give me the single highest value fix. One final agent ranks every skill worst to best.&quot;</p></blockquote><p>Claude asked permission to run a dynamic workflow. I had to explicitly say yes. While it ran, /workflows showed me everything live. All 41 agents, what skill each was on, tokens used, tools, and how long each had been running.</p><p>One gotcha: the JavaScript file doesn&#39;t always land in your project. By default it saved somewhere more global. Tell it to drop the file into <code>.claude/workflows/</code>.</p><h2 id="ultracode-and-deep-research" tabindex="-1">ultracode And /deep-research <a class="header-anchor" href="#ultracode-and-deep-research" aria-label="Permalink to &quot;ultracode And /deep-research&quot;">​</a></h2><p>Run <code>/effort</code> to set your reasoning level: low, medium, high, xhigh, max, then <strong>ultracode</strong>.</p><p>ultracode runs xhigh reasoning and turns basically every prompt into a workflow. It bypasses a lot of permissions and just starts orchestrating.</p><p>Type &quot;workflow&quot; in a turn and it lights up in rainbow. The most reliable trigger: &quot;set me up a dynamic workflow to do this.&quot;</p><p><strong>/deep-research</strong>: automatically kicks off a workflow, spins up agents to research in parallel, has them vote on each claim, and hands back a cited research report.</p><h2 id="the-whole-thing-in-one-slide" tabindex="-1">The Whole Thing In One Slide <a class="header-anchor" href="#the-whole-thing-in-one-slide" aria-label="Permalink to &quot;The Whole Thing In One Slide&quot;">​</a></h2><p>→ Quick one-off → just ask Claude Code. → Something you repeat → make it a Skill. → Messy side task → Subagent. → A small crew that needs to talk → Agent Team. → Keep going until a goal is met → /goal. → A giant parallel job → dynamic workflow. Just be careful.</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>10/10</td><td>完整提示詞、成本控制、.claude/workflows/ 保存路徑、/workflows 監控均直接可套用</td></tr><tr><td>B. 創新性 (20%)</td><td>9/10</td><td>Skill→Subagent→AgentTeam→/goal→Workflow 階梯框架是全網首創系統化整理</td></tr><tr><td>C. 證據品質 (20%)</td><td>9/10</td><td>41 個 Skill 實驗、5M tokens、燒掉 $100 plan 的真實量化教訓</td></tr><tr><td>D. 技術深度 (15%)</td><td>9/10</td><td>/goal（depth）vs workflow（width）對比、ultracode 機制、/deep-research 說明深度完整</td></tr><tr><td>E. 泛化性 (15%)</td><td>9/10</td><td>全框架適用所有 Claude Code 用戶，從新手到進階</td></tr><tr><td><strong>加權總分</strong></td><td><strong>9.3/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：階梯框架和成本控制原則是 dynamic-workflows SKILL 的核心骨架，應作為主要參考整合。</p>',58)])])}const w=t(l,[["render",n]]);export{c as __pageData,w as default};
